import {analyticsSnapshot} from './lab-analytics-model.js';
export function createLabAnalytics(){
 const root=document.createElement('section');root.className='lab-analytics';root.setAttribute('aria-label','Match analytics and prediction');
 root.innerHTML='<div class="analytics-heading"><div><span class="eyebrow">THE NUMBERS / THE NEXT QUESTION</span><h2>Read the match. Test an expectation.</h2></div><button class="analytics-export" disabled>Export analysis ↓</button></div><p class="analytics-status" role="status">Start a fixture to populate this panel with received events. No model requests are used for these calculations.</p><div class="analytics-teams"></div><details><summary>How the estimate works</summary><p>The next-pass estimate is (completed + 1) ÷ (attempted + 2): a smoothed baseline using only received passes. It assumes the next pass resembles this sample. It ignores pressure, location, player and pass difficulty. It is not trained, calibrated or suitable for betting.</p><p>The displayed 95% Wilson interval describes uncertainty in the observed completion rate under an independent-pass assumption. It is not a prediction interval. Football passes are dependent, so actual uncertainty may be larger.</p></details>';
 document.querySelector('.studio-grid').before(root);let latest=null,generation=0,liveActive=false;
 const sample=document.createElement('button');sample.className='analytics-export';sample.textContent='Explore sample · no AI';root.querySelector('.analytics-heading').append(sample);
 sample.onclick=async()=>{if(liveActive)return;const ticket=++generation;sample.disabled=true;try{const response=await fetch('assets/analytics-sample.json');if(!response.ok)throw Error('Unavailable');const data=await response.json();if(ticket!==generation)return;render(data.stats);latest.source=data.source;root.querySelector('.analytics-status').textContent=data.source+' · preview only, not your running fixture';}catch{root.querySelector('.analytics-status').textContent='Sample unavailable. Start a fixture to see live analytics.';}finally{sample.disabled=liveActive;}};
 const exportButton=root.querySelector('button');exportButton.onclick=()=>{if(!latest)return;const url=URL.createObjectURL(new Blob([JSON.stringify({source:'synthetic-received-events',method:'Laplace-smoothed next-pass baseline; Wilson interval for observed rate',...latest},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='btr-match-analytics.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 function render(stats){latest=stats?analyticsSnapshot(stats):null;exportButton.disabled=!latest;const list=root.querySelector('.analytics-teams');list.replaceChildren();root.querySelector('.analytics-status').textContent=stats?`Evidence through ${Math.floor(stats.second/60)}:${String(Math.floor(stats.second%60)).padStart(2,'0')} · ${stats.events} received events · illustrative baseline, not a calibrated forecast`:'Start a fixture to populate this panel with received events. No model requests are used for these calculations.';
 for(const [i,name]of ['Harbor FC','Northbridge'].entries()){const t=latest?.teams[i],p=t?.passes,card=document.createElement('article');card.className='analytics-team '+(i?'away':'home');const percentage=v=>(v*100).toFixed(1)+'%';card.innerHTML=`<h3>${name}</h3><div class="analytics-kpis"><div><span>NEXT PASS · BASELINE</span><strong>${p?percentage(p.probability):'—'}</strong></div><div><span>COMPLETED / ATTEMPTED</span><strong>${p?p.completed+' / '+p.attempts:'—'}</strong></div></div><div class="analytics-bar"><i style="width:${p?p.observed*100:0}%"></i></div><p>${p?'Observed completion '+percentage(p.observed)+' · 95% interval '+percentage(p.low)+'–'+percentage(p.high):'Waiting for the first pass. No invented probability.'}</p><div class="analytics-foot"><span>${t?t.shots:'—'} shots</span><span>${t?t.pressures:'—'} pressure events</span><span>${t?t.possession:'—'}% possession</span></div>${p&&p.attempts<20?'<small>Small sample — treat this estimate cautiously.</small>':''}`;list.append(card);}
 }
 render(null);return {render(stats){generation++;liveActive=!!stats;sample.disabled=liveActive;render(stats);}};
}

